<?php require_once __DIR__.'/includes/permissions.php'; require_permission('dashboard.view'); $title='Dashboard'; $u=current_user(); $pdo=db(); $stats=[]; foreach(['Residents'=>'SELECT COUNT(*) FROM residents WHERE status="Active"','Today’s Appointments'=>'SELECT COUNT(*) FROM appointments WHERE appointment_date=CURDATE() AND status IN ("Pending","Scheduled")','Pending Appointments'=>'SELECT COUNT(*) FROM appointments WHERE status="Pending"','Completed Appointments'=>'SELECT COUNT(*) FROM appointments WHERE status="Completed"','Health Records'=>'SELECT COUNT(*) FROM health_records WHERE status="Active"','Vaccinations'=>'SELECT COUNT(*) FROM vaccinations WHERE status="Active"','Active Programs'=>'SELECT COUNT(*) FROM health_programs WHERE status="Active"'] as $k=>$q)$stats[$k]=(int)$pdo->query($q)->fetchColumn(); $svc=$pdo->query('SELECT s.name,COUNT(a.id) total FROM services s LEFT JOIN appointments a ON a.service_id=s.id GROUP BY s.id ORDER BY total DESC')->fetchAll(); include __DIR__.'/includes/header.php'; ?><div class="page-head"><div><h1>Dashboard</h1><p>Overview of current CHO activity.</p></div></div><div class="row g-3"><?php foreach($stats as $k=>$v):?><div class="col-6 col-xl"><div class="stat-card"><div class="stat-icon"><i class="bi bi-activity"></i></div><span><?=e($k)?></span><strong><?=number_format($v)?></strong></div></div><?php endforeach;?></div><div class="row g-4 mt-1"><div class="col-lg-7"><div class="panel"><div class="panel-head"><h5>Appointments by Service</h5></div><canvas id="serviceChart" height="120"></canvas></div></div><div class="col-lg-5"><div class="panel"><div class="panel-head"><h5>Quick Access</h5></div><div class="quick-grid"><?php if(can('residents.view')):?><a href="residents.php"><i class="bi bi-people"></i>Residents</a><?php endif;if(can('appointments.view')):?><a href="appointments.php"><i class="bi bi-calendar2-check"></i>Appointments</a><?php endif;if(can('ocr.view')):?><a href="ocr.php"><i class="bi bi-file-earmark-text"></i>OCR</a><?php endif;if(can('reports.view')):?><a href="reports.php"><i class="bi bi-file-bar-graph"></i>Reports</a><?php endif;?></div></div></div></div><script>new Chart(document.getElementById('serviceChart'),{type:'bar',data:{labels:<?=json_encode(array_column($svc,'name'))?>,datasets:[{label:'Appointments',data:<?=json_encode(array_map('intval',array_column($svc,'total')))?>}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});</script><?php include __DIR__.'/includes/footer.php'; ?>
